/**
 * 화면명   : page.js
 * 화면기능 : page 관련 유틸리티
 * 작성자   : 차주영
 */

import { ref, computed, watch } from 'vue'

export function usePaging(onGetList, options = {}) {
	const page = ref(options.page ?? 1)
	const pageSize = ref(options.pageSize ?? 20)
	const totalCount = ref(options.totalCount ?? 0)

	const totalPages = computed(() => {
		const size = Number(pageSize.value || 1)
		return Math.max(1, Math.ceil(Number(totalCount.value || 0) / size))
	})

	const setTotalCount = (val) => {
		totalCount.value = Number(val || 0)
	}

	const setPage = (val) => {
		page.value = Number(val || 1)
	}

	const getPage = () => onGetList?.()

	const resetPage = () => {
		page.value = 1
	}

	const resetPageAndGet = () => {
		page.value = 1
		return onGetList?.()
	}

	watch(page, () => {
		onGetList?.()
	})

	return {
		page,
		pageSize,
		totalCount,
		totalPages,

		setTotalCount,
		setPage,

		getPage,
		resetPage,
		resetPageAndGet,
	}
}

/**
 * page / pageSize → start, end index 변환
 * page=1, size=10 → start=0, end=9
 */
export function toStartEndIndex(page, pageSize) {
	const p = Math.max(1, Number(page || 1))
	const s = Math.max(1, Number(pageSize || 1))

	const start = (p - 1) * s
	const end = start + s - 1

	return { start, end }
}
