import { describe, it, expect, vi, afterEach } from 'vitest'
import { nextTick, effectScope } from 'vue'

import { usePaging, toStartEndIndex } from '@/utils/page.js'

describe('toStartEndIndex', () => {
	it('page/pageSize 를 start/end 인덱스로 변환한다', () => {
		expect(toStartEndIndex(1, 10)).toEqual({ start: 0, end: 9 })
		expect(toStartEndIndex(3, 20)).toEqual({ start: 40, end: 59 })
	})

	it('0 이하/비정상 값은 최소값으로 보정한다', () => {
		expect(toStartEndIndex(0, 10)).toEqual({ start: 0, end: 9 })
		expect(toStartEndIndex(-5, 0)).toEqual({ start: 0, end: 0 })
		expect(toStartEndIndex(null, null)).toEqual({ start: 0, end: 0 })
	})
})

describe('usePaging', () => {
	const scopes = []
	const createPaging = (...args) => {
		const scope = effectScope()
		scopes.push(scope)
		return scope.run(() => usePaging(...args))
	}
	afterEach(() => scopes.splice(0).forEach(scope => scope.stop()))

	it('기본값을 설정한다', () => {
		const { page, pageSize, totalCount, totalPages } = createPaging()
		expect(page.value).toBe(1)
		expect(pageSize.value).toBe(20)
		expect(totalCount.value).toBe(0)
		expect(totalPages.value).toBe(1)
	})

	it('totalCount / pageSize 로 전체 페이지 수를 계산한다', () => {
		const { setTotalCount, pageSize, totalPages } = createPaging(null, { pageSize: 10 })
		setTotalCount(95)
		expect(totalPages.value).toBe(10)

		pageSize.value = 30
		expect(totalPages.value).toBe(4)
	})

	it('페이지가 바뀌면 목록 조회 콜백을 호출한다', async () => {
		const onGetList = vi.fn()
		const { setPage } = createPaging(onGetList)

		setPage(3)
		await nextTick()

		expect(onGetList).toHaveBeenCalledTimes(1)
	})

	it('resetPageAndGet 은 1페이지로 되돌리고 조회한다', async () => {
		const onGetList = vi.fn()
		const { page, setPage, resetPageAndGet } = createPaging(onGetList)

		setPage(5)
		await nextTick()
		onGetList.mockClear()

		resetPageAndGet()
		expect(page.value).toBe(1)
		expect(onGetList).toHaveBeenCalledTimes(1)
		await nextTick()
		expect(onGetList).toHaveBeenCalledTimes(1)
	})

	it.each([1, 5])('페이지 %i 초기화는 실제 조회 Promise의 완료와 결과를 전달한다', async (initialPage) => {
		const requests = []
		let complete
		const response = new Promise(resolve => { complete = resolve })
		const paging = createPaging(() => {
			requests.push(paging.page.value)
			return response
		}, { page: initialPage })
		const result = paging.resetPageAndGet()
		expect(paging.page.value).toBe(1)
		expect(result).toBe(response)
		let finished = false
		result.then(() => { finished = true })
		await nextTick()
		expect(finished).toBe(false)
		expect(requests).toEqual([1])
		complete('loaded')
		await expect(result).resolves.toBe('loaded')
		await nextTick()
		expect(finished).toBe(true)
		expect(requests).toEqual([1])
	})

	it('조회 Promise의 거절을 호출자에게 전달한다', async () => {
		const requests = []
		let fail
		const response = new Promise((resolve, reject) => { fail = reject })
		const paging = createPaging(() => {
			requests.push(paging.page.value)
			return response
		}, { page: 5 })
		const error = new Error('조회 실패')
		const rejection = expect(paging.resetPageAndGet()).rejects.toBe(error)
		await nextTick()
		fail(error)
		await rejection
		await nextTick()
		expect(requests).toEqual([1])
	})

	it.each([1, 5])('페이지 %i에서 같은 tick의 이동 후 초기화와 이후 이동을 처리한다', async (initialPage) => {
		const requests = []
		const paging = createPaging(() => requests.push(paging.page.value), { page: initialPage })
		paging.setPage(3)
		paging.resetPageAndGet()
		await nextTick()
		expect(requests).toEqual([1])
		paging.setPage(4)
		await nextTick()
		paging.page.value = 2
		await nextTick()
		expect(requests).toEqual([1, 4, 2])
	})

	it.each([1, 5])('페이지 %i에서 초기화 직후 같은 tick의 다른 페이지 이동을 조회한다', async (initialPage) => {
		const requests = []
		const paging = createPaging(() => requests.push(paging.page.value), { page: initialPage })
		paging.resetPageAndGet()
		paging.page.value = 5
		await nextTick()
		expect(requests).toEqual([1, 5])
		paging.setPage(3)
		await nextTick()
		expect(requests).toEqual([1, 5, 3])
	})

	it('getPage의 결과와 resetPage의 기존 watcher 동작을 유지한다', async () => {
		const requests = []
		const paging = createPaging(() => {
			requests.push(paging.page.value)
			return 'loaded'
		}, { page: 5 })
		expect(paging.getPage()).toBe('loaded')
		expect(paging.resetPage()).toBeUndefined()
		expect(requests).toEqual([5])
		await nextTick()
		expect(requests).toEqual([5, 1])
		paging.resetPage()
		await nextTick()
		expect(requests).toEqual([5, 1])
		expect(paging.resetPageAndGet()).toBe('loaded')
		await nextTick()
		expect(requests).toEqual([5, 1, 1])
	})

	it('scope 종료 후 예약된 watcher와 이후 변경은 조회하지 않는다', async () => {
		const requests = []
		const paging = createPaging(() => requests.push(paging.page.value), { page: 5 })
		paging.resetPageAndGet()
		paging.setPage(2)
		scopes.at(-1).stop()
		await nextTick()
		paging.page.value = 3
		await nextTick()
		expect(requests).toEqual([1])
	})

	it('콜백이 없어도 예외가 발생하지 않는다', async () => {
		const { getPage, resetPageAndGet, setPage, resetPage } = createPaging(undefined, { page: 5 })
		expect(() => getPage()).not.toThrow()
		expect(resetPageAndGet()).toBeUndefined()
		await nextTick()
		setPage(3)
		await nextTick()
		resetPage()
		await nextTick()
	})
})
